#!/bin/bash
fail=0
t=$(mktemp); printf '# h\naoi\t2026-01-01\t10:00\t11:00\tx\nkaede\t2026-01-01\t09:00\t10:00\ty\n' > "$t"
[ "$(BOOKINGS=$t bash src/list.sh --room aoi)" = '2026-01-01 10:00-11:00 aoi x' ] || { echo "list --room"; fail=1; }
[ "$(BOOKINGS=$t bash src/list.sh | head -1)" = '2026-01-01 09:00-10:00 kaede y' ] || { echo "list unchanged"; fail=1; }

# --room と日付を一緒に渡すと、両方で絞る
t2=$(mktemp); printf 'aoi\t2026-01-01\t10:00\t11:00\tx\naoi\t2026-01-02\t12:00\t13:00\tz\nkaede\t2026-01-02\t09:00\t10:00\ty\n' > "$t2"
[ "$(BOOKINGS=$t2 bash src/list.sh --room aoi 2026-01-02)" = '2026-01-02 12:00-13:00 aoi z' ] || { echo "list --room with date"; fail=1; }

# --room に値が無いときは exit 2 と usage を stderr に出す
e=$(mktemp)
BOOKINGS=$t bash src/list.sh --room >/dev/null 2>"$e"; [ $? = 2 ] || { echo "list --room without value should exit 2"; fail=1; }
[ "$(cat "$e")" = 'usage: list.sh [--room ROOM] [DATE]' ] || { echo "list --room without value: usage message"; fail=1; }

rm -f "$t" "$t2" "$e"; exit $fail

